#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn banner_pattern_catalog_is_complete_ordered_and_unique() {
        assert_eq!(VANILLA_BANNER_PATTERN_PRESENTATIONS.len(), 43);
        let mut textures = HashSet::new();
        for entry in VANILLA_BANNER_PATTERN_PRESENTATIONS {
            assert!(textures.insert(entry.texture_ref.path));
            assert!(entry
                .texture_ref
                .size
                .into_iter()
                .all(|dimension| dimension > 0));
        }
    }

    #[test]
    fn banner_pattern_catalog_preserves_asset_mappings() {
        assert_eq!(
            banner_pattern_texture_ref(BannerPatternKind::SmallStripes).path,
            "textures/entity/banner/small_stripes.png"
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_banner_pattern_facts() {
        let fixture = include_str!("tests/banner.rs")
            .split("fn banner_model_keys_and_texture_refs_match_vanilla_selection")
            .nth(1)
            .and_then(|source| source.split("#[test]").next())
            .expect("banner texture fixture");
        assert!(!fixture.contains("BANNER_PATTERN_BASE_TEXTURE_REF.size"));
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/banner_patterns.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if source.contains("fn banner_pattern_texture_ref(")
                    || source.contains("const BANNER_PATTERN_BASE_TEXTURE_REF")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel banner-pattern catalog owners: {violations:?}"
        );
    }
}
